auto partition_map = std::make_unique<std::map<float, BucketPtr>>();
buckets_out.clear();
buckets_out.reserve(num_buckets);

if (num_buckets <= 0) {
    return partition_map;
}

// Create the buckets first
for (int i = 0; i < num_buckets; ++i) {
    std::string name = "bucket_" + std::to_string(i);
    // We initialize with empty points and add them later to ensure balance
    auto bucket = std::make_shared<Bucket>(name, std::vector<float>());
    buckets_out.push_back(bucket);
}

// Distribute partition points uniformly across the unit circle
// Total points = num_buckets * partitions_per_bucket
// The distance between any two consecutive points is 1.0 / total_points
float total_points = static_cast<float>(num_buckets) * partitions_per_bucket;
float step = 1.0f / total_points;

for (int p = 0; p < partitions_per_bucket; ++p) {
    for (int b = 0; b < num_buckets; ++b) {
        // Calculate the point: (p * num_buckets + b) * step
        // This ensures that points are interleaved: B0, B1, ... Bn, B0, B1...
        float point = (static_cast<float>(p) * num_buckets + b) * step;

        BucketPtr bucket = buckets_out[b];
        bucket->add_partition_point(point);
        (*partition_map)[point] = bucket;
    }
}

return partition_map;

